/** Serializable character rules shared by the Inspector and browser runtime. */
export type WebEditMaskCase = 'none' | 'upper' | 'lower';

export interface WebEditMaskToken {
    /** A JavaScript Unicode regular expression matching one complete character. */
    readonly pattern: string;
    readonly transform?: WebEditMaskCase;
}

export type WebEditMaskTokens = Readonly<Record<string, string | WebEditMaskToken>>;

export const DEFAULT_EDIT_MASK_TOKENS: WebEditMaskTokens;

export interface EditMaskResult {
    readonly text: string;
    readonly raw: string;
    readonly complete: boolean;
    /** UTF-16 offsets of editable characters in the formatted value. */
    readonly positions: readonly {
        readonly start: number;
        readonly end: number;
    }[];
    /** Formatted caret offsets indexed by source UTF-16 offset. */
    readonly carets: readonly number[];
}

export interface CompiledEditMask {
    format(value: string, letterCase?: WebEditMaskCase, raw?: boolean): EditMaskResult;
}

export function parseWebEditMaskTokens(value: unknown): WebEditMaskTokens;

/** Bounded pattern grammar: literals, escapes, [optional groups], {min,max} and | alternatives. */
export function compileEditMask(pattern: string, tokens?: WebEditMaskTokens): CompiledEditMask;

export function isWebEditMaskPattern(value: unknown): value is string;

export function isWebEditMaskTokens(value: unknown): value is WebEditMaskTokens;

export type WebInputType = 'text' | 'password' | 'email' | 'number' | 'search' | 'tel' | 'url';

/** An empty string removes the icon. */
export type WebEditIcon = WebButtonIcon | '';

/** A text field with an optional, dynamically configurable character mask. */
export class WebEdit extends WebComponent<HTMLElement> {
    #private;
    constructor(element: HTMLElement);
    get value(): string;
    set value(value: string);
    /** Accepted characters without mask literals. Assign this when input is known to be raw. */
    get rawValue(): string;
    set rawValue(value: string);
    get maskEnabled(): boolean;
    set maskEnabled(value: boolean);
    /** 0 digit, a Unicode letter, * alphanumeric, # any character; escape literals with \\. */
    get mask(): string;
    set mask(value: string);
    /** Custom tokens override built-ins. Each pattern matches one whole Unicode character. */
    get maskTokens(): WebEditMaskTokens;
    set maskTokens(value: WebEditMaskTokens);
    get maskCase(): WebEditMaskCase;
    set maskCase(value: WebEditMaskCase);
    /** True when an active mask has all its required positions filled. Empty is incomplete. */
    get maskComplete(): boolean;
    /** Empty for a valid pattern. Invalid patterns leave the text editable without masking. */
    get maskError(): string;
    get placeholder(): string;
    set placeholder(value: string);
    get readOnly(): boolean;
    set readOnly(value: boolean);
    get inputType(): WebInputType;
    set inputType(value: WebInputType);
    /** Visible, accessible field label. An empty string hides it. */
    get label(): string;
    set label(value: string);
    /** Icon shown inside the field. An empty string removes it. */
    get icon(): WebEditIcon;
    set icon(value: WebEditIcon);
    /** Accessible name of the clickable icon; empty uses the icon and field names. */
    get iconAccessibleLabel(): string;
    set iconAccessibleLabel(value: string);
    get enabled(): boolean;
    set enabled(value: boolean);
    get tabIndex(): number;
    set tabIndex(value: number);
    focus(options?: FocusOptions): void;
    clear(): void;
    set onChange(handler: WebComponentEventHandler<this> | null);
    set onInput(handler: WebComponentEventHandler<this> | null);
    /** Binds the icon action, enabling its native button and hover feedback. */
    set onIconClick(handler: ((sender: this, event: MouseEvent) => void | Promise<void>) | null);
    bindEvent(eventName: string, handler: WebComponentEventHandler<this> | null): () => void;
    dispose(): void;
}

/** Project-model projection used by Designer, Preview and exported applications. */
export function configureWebEdit(component: WebEdit, props: Readonly<Record<string, unknown>>): void;
